---@module 'hl'

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pamixer --increase 5 && ~/scripts/volume_osd.sh"), { locked = true })

hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pamixer --decrease 5 && ~/scripts/volume_osd.sh"), { locked = true })

